		t.Fatalf("plan mutated after failed update: %+v", got)
	}
	if err := s.UpdatePlan(Plan{ID: "missing", TaxRateBasisPoints: 1}); !errors.Is(err, ErrPlanNotFound) {
		t.Fatalf("update missing: %v", err)
	}
}

