cp meter/service.go /tmp/service.go.bak && python3 - <<'EOF'
import re
p='meter/service.go'
src=open(p).read()
old='''	// 已有安排且目标相同：原样返回，不重新取价。
	if acc.sub.pending != nil && acc.sub.pending.TargetPlanID == targetPlanID {
		return PlanChangeResult{Created: false, Change: *acc.sub.pending}, nil
	}
'''
buggy='''	// BUG-INJECT: 复用该账户此前为该目标保存过的安排（即使已被替换）。
	if old, ok := acc.sub.pendingHistory[targetPlanID]; ok {
		return PlanChangeResult{Created: false, Change: old}, nil
	}
	if acc.sub.pending != nil && acc.sub.pending.TargetPlanID == targetPlanID {
		return PlanChangeResult{Created: false, Change: *acc.sub.pending}, nil
	}
'''
assert old in src
src=src.replace(old,buggy)
src=src.replace('''	pending *PlanChange
''','''	pending        *PlanChange
	pendingHistory map[string]PlanChange
''')
src=src.replace('''	acc.sub.pending = &change
	return PlanChangeResult{Created: true, Change: change}, nil''','''	if acc.sub.pendingHistory == nil {
		acc.sub.pendingHistory = map[string]PlanChange{}
	}
	acc.sub.pendingHistory[targetPlanID] = change
	acc.sub.pending = &change
	return PlanChangeResult{Created: true, Change: change}, nil''')
open(p,'w').write(src)
EOF
